import{z as s,x as C,o as A,c as p,q as o,j as r,D as e,d as t,s as l,S as n,b as a}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"DTCO","description":"","frontmatter":{"title":"DTCO","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/dtco-patterning.md","filePath":"litho/dtco-patterning.md","lastUpdated":1791063341000}'),B={name:"litho/dtco-patterning.md"};function d(D,E,T,h,c,m){const i=C("Mermaid");return A(),p("div",null,[E[2]||(E[2]=o('<h1 id="dtco" tabindex="-1">DTCO <a class="header-anchor" href="#dtco" aria-label="Permalink to &quot;DTCO&quot;">​</a></h1><div class="epigraph"><p>设计规则不是从瑞利公式抄下来的整数；它们是单元库、布线、光刻分解与刻蚀一起谈出来的可行集，这个过程叫设计–工艺协同优化。</p><footer>—— 对照 imec 对 DTCO 与先进节点图形化路径的公开论述</footer></div><p><a href="/litho/hotspot-fix">上一课</a>（热点修复）把压不住的局部热点分三轨处置，并把重复热点升级成改库的诉求。缺口是：再快的 OPC 也救不回一套与工艺作对的库。标准单元轨道高度、允许节距、通孔网格、是否让某层走 <a href="/litho/euv-double-pattern">EUV 双重</a> 或 SAQP，必须在设计时就选好。imec 把这套闭环称作 DTCO（Design–Technology Co-Optimization）。本课钉图形化侧的协同，也是计算光刻与掩模写入课程的末课；紧凑模型对严格电磁的分工，<a href="/litho/compact-vs-rigorous">前面</a>已经钉过。版图怎么交到掩模厂，<a href="/litho/gdsii-oasis">下一课</a>从 GDSII 与 OASIS 另起。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(k_1\\)、随机悬崖、套刻、胶厚、掩模 MRC，每一课都在收缩「能印的多边形集合」。若库仍按上一代的最小节距和二维自由度去画，OPC/ILT 只能在错误可行集里修碎形，窗口交为空。DTCO 的问题是反过来：在给定机台（0.33 / 0.55）、胶与分解选项下，选一组设计规则和单元架构，使关键层落在可印集合内，同时电学与密度可接受。</p><p><span class="marginnote">DTCO 翻译过来就是「设计–工艺协同优化」：在设计规则定稿之前，让画版图的人与管机台、管刻蚀的人坐在同一张桌上谈判，互相给出可选集与代价，直到密度、功耗、良率都能交货。它不是某一款软件，而是一个来回迭代的流程。</span></p><p>公开例子包括：用一维金属栅加切线换二维自由布线；用轨道高度和 FinFlex 一类库选项换密度；在「EUV 单次 / EUV 双重 / DUV 多重」之间按层挑选，而不是全球一句「本节点全 EUV」。imec 的 DTCO 叙事把光刻选项与标准单元、SRAM、互连一起评估，而不是先定库再把光刻当装饰。</p><h3 id="dtco-不是「让设计遵守-drc」" tabindex="-1">DTCO 不是「让设计遵守 DRC」 <a class="header-anchor" href="#dtco-不是「让设计遵守-drc」" aria-label="Permalink to &quot;DTCO 不是「让设计遵守 DRC」&quot;">​</a></h3><p>DRC 是协同的<strong>输出</strong>。DTCO 是产生 DRC 的循环：工艺给出可印节距与分解成本，设计给出库与布线需求，两边改，直到密度、功耗、循环时间可交货。把已冻结的 DRC 手册叫做 DTCO，等于把结果当成过程。</p><p><span class="marginnote">直觉类比：先锁库再上 OPC，就像先装修完再想改承重墙——墙（版图拓扑）已经定死，修补（OPC）只能在表面刮腻子。DTCO 是在画图纸阶段就把承重墙和管线一起谈好，装修阶段才不必动结构。</span></p><p><span class="marginnote">DTCO 跨设计与工艺，但本课只写图形化闭环。器件静电学（FinFET/GAA）有自己的课，不在这里重讲纳米片释放。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>循环大致是：候选设计规则（节距、取向、通孔网格、切线策略）→ 代表性标准单元与 SRAM → SMO/OPC/ILT 与随机预算 → 分解层数与套刻账 → 改规则或改库 → 再评估。计算光刻在这里是评估器，不是事后修补。GPU 与 ML 缩短每一圈的墙钟，使规则还能在定节点前多转几圈，但不能替代圈本身。</p><p>与 High-NA 半场的协同：大 die 是否接受拼接、是否改用芯粒避开半场，是 DTCO 而不是只买 EXE。与 GAA 的协同：片宽可调改变单元的 drive 档，布线 congest 形状变，金属层的可印网格要重谈。</p><h3 id="成本函数是节点-不是一层的-epe" tabindex="-1">成本函数是节点，不是一层的 EPE <a class="header-anchor" href="#成本函数是节点-不是一层的-epe" aria-label="Permalink to &quot;成本函数是节点，不是一层的 EPE&quot;">​</a></h3><p>某一层用 SAQP 可以把 EPE 做得很好，却把切线套刻和薄膜均匀性变成全芯片良率项。DTCO 的成本是周期时间、掩模数、wph、缺陷与电学的交，而不是 OPC 报表上的纳米。imec 公开比较多种图形化路径时，用的正是这种节点级权衡，而不是单一热区窗口。</p><p><span class="marginnote">数字实例：同一个金属层节距——EUV 单次约 1 张掩模；EUV 双重约 2 张掩模加 1 次严格套刻；SAQP 是 1 次心棒光刻、两轮沉积与侧墙刻蚀、再加 2-3 张切割掩模。掩模数与套刻敏感度成倍翻，这就是节点成本函数里「不止一层 EPE」的账。</span></p>',17)),(A(),r(n,null,{default:e(()=>[l(i,{id:"mermaid-49",class:"mermaid",graph:"flowchart%20TD%0A%20%20HP%5B%22%E8%AF%A5%E5%B1%82%E8%8A%82%E8%B7%9D%E4%B8%8E%E5%AF%86%E5%BA%A6%E9%9C%80%E6%B1%82%22%5D%20--%3E%20Q%7B%22%E5%8D%95%E6%AC%A1%E5%8F%AF%E5%8D%B0%EF%BC%9F%22%7D%0A%20%20Q%20--%3E%7C%22%E6%98%AF%22%7C%20S%5B%22EUV%20%E5%8D%95%E6%AC%A1%EF%BC%9A1%20%E5%BC%A0%E6%8E%A9%E6%A8%A1%22%5D%0A%20%20Q%20--%3E%7C%22%E5%90%A6%22%7C%20Q2%7B%22%E5%8F%AF%E6%8E%A5%E5%8F%97%E5%87%A0%E6%AC%A1%E5%A5%97%E5%88%BB%EF%BC%9F%22%7D%0A%20%20Q2%20--%3E%7C%22%E4%B8%A4%E6%AC%A1%E4%BB%A5%E5%86%85%22%7C%20DP%5B%22EUV%20%E5%8F%8C%E9%87%8D%EF%BC%9A2%20%E5%BC%A0%E6%8E%A9%E6%A8%A1%22%5D%0A%20%20Q2%20--%3E%7C%22%E8%8A%82%E8%B7%9D%E5%A4%AA%E7%B4%A7%22%7C%20SP%5B%22SAQP%EF%BC%9A%E5%BF%83%E6%A3%92%20%2B%20%E4%B8%A4%E8%BD%AE%E4%BE%A7%E5%A2%99%22%5D%0A%20%20DP%20--%3E%20CUT%5B%22%E5%88%87%E5%89%B2%E6%8E%A9%E6%A8%A1%E8%B4%A6%22%5D%0A%20%20SP%20--%3E%20CUTS%5B%222-3%20%E5%BC%A0%E5%88%87%E5%89%B2%E6%8E%A9%E6%A8%A1%22%5D%0A%20%20S%20--%3E%20TC%5B%22%E8%8A%82%E7%82%B9%E6%88%90%E6%9C%AC%E5%87%BD%E6%95%B0%EF%BC%9A%E6%8E%A9%E6%A8%A1%2F%E5%A5%97%E5%88%BB%2F%E9%9A%8F%E6%9C%BA%22%5D%0A%20%20CUT%20--%3E%20TC%0A%20%20CUTS%20--%3E%20TC%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[t(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[t("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,"设计多边形进入成像算子之前，已经被规则投影到「友好节距 / 取向」的子集。SMO 在这个子集上才有窗口交；OPC 在这个子集上才收敛。若子集选错，自由光瞳与曲线 ILT 只是对抽样 clips 有效。DTCO 把规则子集当成优化变量之一，与光源、分解一起走——比 SMO 多一层「哪些图形允许存在」。",-1)),E[5]||(E[5]=a("p",null,"反向通道：工艺发现某类二维拐角不可印，就禁止或改成切线架构，而不是要求 ILT 无限正则。库、光刻、掩模厂 MRC 在同一张可行集上对齐，TAPOUT 才不会在 MRC 或随机悬崖上突然翻车。",-1)),E[6]||(E[6]=a("p",null,[a("span",{class:"marginnote"},"FinFlex、COAG、单扩散断裂一类，是 DTCO 的库杠杆，不是光刻算法。写节点对比时把「库架构收益」和「NA / 波长收益」分开，避免把商标当分辨率。")],-1)),(A(),r(n,null,{default:e(()=>[l(i,{id:"mermaid-62",class:"mermaid",graph:"flowchart%20TD%0A%20%20LIB%5B%22%E5%8D%95%E5%85%83%E5%BA%93%20%2F%20%E5%B8%83%E7%BA%BF%E7%BD%91%E6%A0%BC%22%5D%20--%3E%20RULE%5B%22%E8%AE%BE%E8%AE%A1%E8%A7%84%E5%88%99%E5%80%99%E9%80%89%22%5D%0A%20%20LITH%5B%22%E6%9C%BA%E5%8F%B0%20%2F%20%E8%83%B6%20%2F%20%E5%88%86%E8%A7%A3%22%5D%20--%3E%20EVAL%5B%22SMO%20OPC%20%E9%9A%8F%E6%9C%BA%20%E5%A5%97%E5%88%BB%22%5D%0A%20%20RULE%20--%3E%20EVAL%0A%20%20EVAL%20--%3E%20TRADE%5B%22%E5%AF%86%E5%BA%A6-%E5%BE%AA%E7%8E%AF-%E8%89%AF%E7%8E%87%22%5D%0A%20%20TRADE%20--%3E%20LIB%0A%20%20TRADE%20--%3E%20LITH%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[t(" Loading... ",-1)])]),_:1})),E[7]||(E[7]=o('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>DTCO 不增加 NA，不创造光子。它只避免在不可印集合上浪费计算光刻。协同失败的典型症状是：OPC 日历爆炸、热区在量产中途冒出、N3E 一类「放松节距退回单次」的成本修复。公开节点故事可以引用这类权衡，不要编未公布的规则数值。</p><p>后课默认：设计规则是 DTCO 的产物；紧凑成像模型是评估器里跑得最快的那一层，其与严格电磁的差，<a href="/litho/compact-vs-rigorous">紧凑模型对严格电磁</a>一课已经钉过。</p><p><span class="marginnote">引用 imec DTCO 时写清比较的是哪一种图形化路径（EUV 单次、双重、SAQP）与哪一类单元。只展示一张标准单元漂亮图，不是协同已经完成。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>DTCO 让设计规则、单元库与光刻分解在同一可行集上闭环。</li><li>DRC 是协同的输出；先锁库再 OPC，会把修正链困在错误集合里。</li><li>评估必须按节点成本（循环、掩模、随机、套刻），不能只看一层 EPE。</li><li>计算加速让闭环多转几圈，不替代规则与库的决策。</li><li>出处：imec 对 DTCO 与先进节点图形化路径的公开论述。</li></ul>',6))])}const F=s(B,[["render",d]]);export{P as __pageData,F as default};
